import { useState, useEffect } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import { useAuth } from '@/app/providers/AuthProvider'
import { profilesService } from '@/integrations/supabase/profiles'

export function ProfileOverviewPage() {
  const { user } = useAuth()
  const qc = useQueryClient()
  const [displayName, setDisplayName] = useState('')

  const { data: profile } = useQuery({
    queryKey: ['profile', user?.id],
    queryFn: () => profilesService.getProfile(user!.id),
    enabled: !!user,
  })

  useEffect(() => {
    setDisplayName(profile?.displayName ?? user?.displayName ?? '')
  }, [profile, user])

  const saveMut = useMutation({
    mutationFn: () => profilesService.updateProfile(user!.id, { displayName }),
    onSuccess: () => {
      toast.success('Profile updated')
      qc.invalidateQueries({ queryKey: ['profile', user?.id] })
    },
    onError: (e: Error) => toast.error(e.message),
  })

  return (
    <div className="h-full overflow-y-auto p-6">
      <div className="max-w-2xl mx-auto">
        <div className="bg-surface rounded-xl border border-border p-6">
          <div className="flex items-center gap-4 mb-6">
            <div className="h-14 w-14 rounded-full bg-accent/20 flex items-center justify-center text-xl font-bold text-accent">
              {(displayName || user?.displayName || 'U').charAt(0).toUpperCase()}
            </div>
            <div>
              <p className="font-semibold">{displayName || user?.displayName}</p>
              <p className="text-sm text-muted-foreground">{user?.email}</p>
            </div>
          </div>
          <div className="flex flex-col gap-4">
            <div>
              <label className="text-sm font-medium block mb-1.5">Display name</label>
              <input value={displayName} onChange={(e) => setDisplayName(e.target.value)} className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent" />
            </div>
            <button onClick={() => saveMut.mutate()} disabled={saveMut.isPending} className="self-start bg-accent text-accent-foreground px-4 py-2 rounded-lg text-sm hover:opacity-90 disabled:opacity-50">
              {saveMut.isPending ? 'Saving…' : 'Save'}
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}
